class Solution:
    def bestScore(self, stones: List[int], k: int) -> int:
        n = len(stones)
        best = [0] * n
        best[0] = stones[0]
        for i in range(1, n):
            top = best[i - 1]
            for j in range(max(0, i - k), i):
                top = max(top, best[j])
            best[i] = stones[i] + top
        return best[-1]

