class Solution {
    public long bestScore(int[] stones, int k) {
        int n = stones.length;
        long[] best = new long[n];
        best[0] = stones[0];
        for (int i = 1; i < n; i++) {
            long top = best[i - 1];
            for (int j = Math.max(0, i - k); j < i; j++) top = Math.max(top, best[j]);
            best[i] = stones[i] + top;
        }
        return best[n - 1];
    }
}

