    long long* best = malloc(n * sizeof(long long));
    best[0] = stones[0];
    for (int i = 1; i < n; i++) {
        long long top = best[i - 1];
        for (int j = i - k > 0 ? i - k : 0; j < i; j++) if (best[j] > top) top = best[j];
        best[i] = stones[i] + top;
    }
    long long answer = best[n - 1];
    free(best);
    return answer;
