class Solution {
    public long bestScore(int[] stones, int k) {
        int n = stones.length;
        long[] best = new long[n];
        int[] dq = new int[n];
        int head = 0, tail = 0;
        best[0] = stones[0];
        dq[tail++] = 0;
        for (int i = 1; i < n; i++) {
            if (dq[head] < i - k) head++;
            best[i] = stones[i] + best[dq[head]];
            while (tail > head && best[dq[tail - 1]] <= best[i]) tail--;
            dq[tail++] = i;
        }
        return best[n - 1];
    }
}

