class Solution {
public:
    long long bestScore(vector<int>& stones, int k) {
        int n = stones.size();
        vector<long long> best(n);
        deque<int> dq;
        best[0] = stones[0];
        dq.push_back(0);
        for (int i = 1; i < n; i++) {
            if (dq.front() < i - k) dq.pop_front();
            best[i] = stones[i] + best[dq.front()];
            while (!dq.empty() && best[dq.back()] <= best[i]) dq.pop_back();
            dq.push_back(i);
        }
        return best[n - 1];
    }
};

